def need(ok,message):
    if not ok:raise RuntimeError(message)


def sha(path):
    p=Path(path);need(p.resolve(strict=True)==p,'Redirected input')
    with p.open('rb') as f:
        before=os.fstat(f.fileno());need(stat.S_ISREG(before.st_mode) and before.st_size<=128*1024**2,'Unexpected input type/size')
        h=hashlib.sha256()
        for chunk in iter(lambda:f.read(1024**2),b''):h.update(chunk)
        after=os.fstat(f.fileno())
    need((before.st_dev,before.st_ino,before.st_size,before.st_mtime_ns)==(after.st_dev,after.st_ino,after.st_size,after.st_mtime_ns),'Input changed')
    return h.hexdigest()


def read(path):
    p=Path(path);need(p.resolve(strict=True)==p,'Redirected receipt')
    with p.open('rb') as f:
        m=os.fstat(f.fileno());need(stat.S_ISREG(m.st_mode) and m.st_uid==1204 and m.st_size<=1024**2,'Receipt identity differs')
        raw=f.read(1024**2+1);after=os.fstat(f.fileno())
    need(len(raw)==m.st_size and (m.st_ino,m.st_size,m.st_mtime_ns)==(after.st_ino,after.st_size,after.st_mtime_ns),'Receipt changed')
    return json.loads(raw)


