def previous_initial_failure_proof():
    import fcntl
    groups=os.getgroups()
    need(984 in groups and set(groups)<={36,984,1205},'Run only in the reviewed transient ubsmd supplementary-group unit')
    for name,pin in OLD_PINS.items():need(sha(ROOT/name)==pin,'Prior failed importer source changed; preserve it')
    before=read(OLD_SESSION/'return.json');pending=read(OLD_PENDING);owner=read(OLD_SESSION/'provider/owner.json');config=read(OLD_SESSION/'config.json');old_manifest=read(OLD_SESSION/'owner-manifest.json')
    expected=manifest()
    protocol_bytes=json.dumps(old_manifest,separators=(',',':'),ensure_ascii=False).encode()
    sorted_bytes=json.dumps(old_manifest,separators=(',',':'),sort_keys=True).encode()
    need(old_manifest==expected and hashlib.sha256(protocol_bytes).hexdigest()==MANIFEST_SHA,'Old failed session does not match exact A manifest semantics/protocol digest')
    need(before.get('revision')=='B-import-release-only-v1' and before.get('status')=='STOPPED_B_IMPORT_RELEASE_PRESERVE_RECEIPTS'
         and before.get('errorType')=='SdkError' and before.get('reason')=='SDK initialize failed: rc=6015'
         and before.get('ownerId')==expected['ownerId'],'Prior failure is not the exact pre-map initialization failure')
    need(pending.get('revision')=='B-import-release-only-v1' and pending.get('node')=='node-b'
         and pending.get('state')=='intent_before_sdk' and pending.get('workDir')==str(OLD_SESSION/'provider')
         and pending.get('ownerId')==expected['ownerId'],'Original failed pending differs; preserved')
    need(owner.get('role')=='import' and owner.get('mode')=='pmem' and owner.get('state')=='released'
         and owner.get('format')=='native-raw-v1' and owner.get('objects')==[] and 'imports' not in owner
         and owner.get('errorType')=='SdkError' and owner.get('reason')=='SDK initialize failed: rc=6015'
         and owner.get('ownerId') is None and owner.get('base_post_sha256_verified') is None,'Prior SDK attempt may have reached a named map; no retry')
    need(config.get('role')=='import' and config.get('mode')=='pmem' and config.get('readerId')=='node-b'
         and config.get('workDir')==str(OLD_SESSION/'provider') and config.get('manifest')==str(OLD_SESSION/'owner-manifest.json')
         and config.get('logicalBudgetBytes')==64*1024**2 and config.get('maxCoverageBytes')==128*1024**2,'Prior import config differs')
    for leaf in ('data.sock','control.sock','release.json'):
        path=OLD_SESSION/'provider'/leaf;need(not path.exists() and not path.is_symlink(),'Prior provider/release endpoint remains; no retry')
    path=OLD_SESSION/'provider/generation.lock'
    need(path.resolve(strict=True)==path,'Prior generation lock redirected')
    fd=os.open(path,os.O_RDONLY|os.O_NOFOLLOW|os.O_CLOEXEC)
    try:
        info=os.fstat(fd);need(stat.S_ISREG(info.st_mode) and info.st_uid==1204 and info.st_nlink==1,'Prior generation lock identity differs')
        fcntl.flock(fd,fcntl.LOCK_EX|fcntl.LOCK_NB)
    except BaseException:os.close(fd);raise
    OLD_GENERATION_LOCKS.append(fd)
    return {'status':'EXACT_PRIOR_INITIALIZE_FAILURE_BEFORE_NAMED_MAP_REVIEWED',
        'oldReceiptPreserved':True,'oldSourcePinsMatch':True,'oldNamedMapRecordAbsent':True,
        'oldProviderEndpointsAbsent':True,'oldGenerationLockHeld':True,'sdkCoordinationLockAlreadyHeld':True,
        'manifestProtocolCanonicalSha256':hashlib.sha256(protocol_bytes).hexdigest(),
        'oldDiagnosticSortedRepresentationSha256':hashlib.sha256(sorted_bytes).hexdigest(),
        'manifestSemanticsMatchExactA':True,'finalizeZeroNotUsedAsSoleProof':True,
        'processScopedAdditionalGroup':984,'hostGroupOrPermissionsChanged':False}


def run_import(config,selected,owner,service,raw,contract,journal,report):
    """No API returns an FD to a Guest. The normal retire path makes the receipt."""
    Original=raw.NativeRawBackend
    created=[]
    class ImportOnly(Original):
        def __init__(self,*a):
            super().__init__(*a);self.read_bytes=0;self.deallocation_calls=0;created.append(self)
        def allocate(self,*a):raise RuntimeError('Allocation is forbidden in this B-only import')
        def deallocate(self,*a):
            self.deallocation_calls+=1
            raise RuntimeError('Owner deletion is forbidden on B')
        def call(self,operation,*args):
            need(operation not in ('allocate','deallocate','write'),'Mutating SDK operation is forbidden on B')
            report['SDK_called']=True
            result=super().call(operation,*args)
            if operation=='read':self.read_bytes+=int(args[-1])
            return result
        def map(self,replica,writable=False):
            need(writable is False,'Writable import is forbidden')
            report['SDK_called']=True
            return super().map(replica,False)
    raw.NativeRawBackend=ImportOnly
    outcome={}
    def retire_after_verified_import():
        try:
            deadline=time.monotonic()+180
            while time.monotonic()<deadline:
                try:
                    state=read(WORK/'owner.json')
                    if state.get('state')=='serving':break
                    if state.get('state')=='unresolved_preserved':return
                except (OSError,ValueError,RuntimeError):pass
                time.sleep(0.1)
            else:
                outcome['error']='IMPORT_NOT_READY_PRESERVE_RECEIPTS_NO_RETRY'
                print('IMPORT_WAIT_EXPIRED_PRESERVE_RECEIPTS_NO_RETRY',flush=True);return
            print('PHASE=B_same_A_object_ready_start_one_DAX_Guest',flush=True)
            guest_result=run_guest_after_import()
            outcome['guest']=guest_result
            if not guest_result.get('safeToRetireThisLease'):
                outcome['error']='GUEST_NOT_DEFINITIVELY_REAPED_PRESERVE_PROVIDER'
                print('B_GUEST_UNRESOLVED_KEEP_PROVIDER_AND_A_OWNER',flush=True)
                return
            print('PHASE=B_Guest_reaped_retire_local_import_maps_only',flush=True)
            with socket.socket(socket.AF_UNIX) as client:
                client.settimeout(180);client.connect(str(WORK/'control.sock'))
                contract.same_uid(client)
                contract.send_json(client,{'operation':'retire','peerReceipts':[]})
                outcome['retire']=contract.receive_json(client)
            if outcome['retire'].get('state')!='released':
                print('B_RETIRE_REFUSED_PRESERVE_LIVE_PROVIDER_AND_RECEIPTS',flush=True)
        except Exception as error:
            outcome['errorType']=type(error).__name__
            print('B_RETIRE_UNCERTAIN_PRESERVE_PROVIDER_AND_RECEIPTS',flush=True)
    thread=threading.Thread(target=retire_after_verified_import,daemon=True)
    thread.start()
    try:
        service.serve(config,selected,owner)
        thread.join(5)
        need(not thread.is_alive() and outcome.get('retire')=={'state':'released'},'B explicit retirement is unconfirmed')
        state=read(WORK/'owner.json')
        need(state.get('state')=='released' and state.get('finalize_acknowledged') is True
             and state.get('base_post_sha256_verified') is True and state.get('objects')==[],
             'B mapping/finalize/post-SHA release evidence is incomplete')
        receipt=read(WORK/'release.json')
        expected={'version':1,'ownerId':owner['ownerId'],'readerId':'node-b',
                  'manifestSha256':service.identity(owner),'state':'released'}
        need(receipt==expected,'Production B release receipt differs from exact A generation')
        need(len(created)==1 and created[0].allocation_calls==0 and created[0].deallocation_calls==0
             and all(mapped.closed for mapped in created[0].mappings),
             'Unexpected allocate/delete operation in B importer')
        report.update(status='B_EXACT_GENERATION_IMPORTED_SHA_VERIFIED_AND_RELEASED',
            state='released',allocationCalls=0,deallocationCalls=0,mappingsReleased=True,finalizeAcknowledged=True,
            fullPayloadShaVerifiedBeforeRelease=True,fullPayloadShaVerifiedAfterImport=True,
            sdkReadBytes=created[0].read_bytes,logicalImageBytes=64*1024**2,
            backingCoverageByObject=created[0].coverage_by_object,
            releaseReceipt=str(WORK/'release.json'),release=receipt,
            releaseBase64=base64.b64encode(contract.canonical(receipt)).decode(),
            releaseCanonicalSha256=hashlib.sha256(contract.canonical(receipt)).hexdigest())
        guest=outcome.get('guest',{})
        accepted=guest.get('guestDaxSelftestPassed') is True and guest.get('firecrackerExit')==0 and guest.get('safeToRetireThisLease') is True
        report.update(status='B_SHARED_BASE_DAX_GUEST_PASSED_AND_RELEASED' if accepted else 'B_GUEST_FAILED_IMPORT_RELEASED',
            Guest_created=guest.get('Guest_created'),KVM_tested=accepted,guestDaxSelftestPassed=accepted,guest=guest,
            fullAgentENVIntegrationAccepted=False,simultaneousTwoNodeGuestsAccepted=False,
            memfilePrivateCowAccepted=False,netPhysicalSavingsAccepted=False)
        journal({'state':'released','SDK_called':True,'mappingsReleased':True,'finalizeAcknowledged':True,
                 'releaseReceipt':str(WORK/'release.json'),'ownerId':owner['ownerId']})
    finally:
        raw.NativeRawBackend=Original


def main():
    p=argparse.ArgumentParser(description=__doc__);p.add_argument('--run',action='store_true');args=p.parse_args()
    owner=manifest()
    report={'revision':'B-native-guest-v4','status':'PLAN_ONLY_NO_SDK','SDK_called':False,
        'Guest_created':False,'KVM_tested':False,'FC_required':True,'services_changed':False,
        'ownerId':owner['ownerId'],'manifestSha256':MANIFEST_SHA,'workDir':str(WORK),
        'allocationPermitted':False,'ownerDeletionPermitted':False,'physicalSharingAccepted':False}
    if not args.run:print(json.dumps(report,indent=2));return 0
    lock=None;session_created=False
    try:
        need(sys.platform=='linux' and platform.machine()=='aarch64' and socket.gethostname()=='agent1','Use ARM64 Linux B/agent1')
        need(os.getuid()==os.geteuid()==1204 and os.getgid()==os.getegid()==1205,'Ordinary jwk only, no sudo')
        caps=dict(line.split(':',1) for line in Path('/proc/self/status').read_text().splitlines() if ':' in line)
        need(all(int(caps[k].strip(),16)==0 for k in ('CapInh','CapPrm','CapEff','CapAmb')),'Zero capabilities required')
        need(os.sysconf('SC_PAGE_SIZE')==4096,'Expected 4096-byte page size')
        import resource,fcntl
        resource.setrlimit(resource.RLIMIT_CORE,(0,0));os.umask(0o077)
        need(BASE.resolve(strict=True)==BASE and BASE.stat().st_uid==1204,'Existing B artifact directory is required')
        lock_path=ROOT/'relay/ub-layer-sdk-node-b.lock'
        need(lock_path.resolve()==lock_path,'SDK lock redirected')
        lock=os.open(lock_path,os.O_RDWR|os.O_CREAT|os.O_NOFOLLOW|os.O_CLOEXEC,0o600)
        m=os.fstat(lock);need(stat.S_ISREG(m.st_mode) and m.st_uid==1204 and m.st_nlink==1,'SDK lock identity differs')
        fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
        prior=types.ModuleType('B_readonly_prior_receipts');exec(compile(PAYLOAD['prior'],'<prior>','exec'),prior.__dict__)
        report['priorReceipts']=prior.check_prior_receipts(str(ROOT),'node-b')
        report['previousFailureProof']=previous_failure_proof()
        report['processGroups']=os.getgroups()
        need(984 in os.getgroups() and set(os.getgroups())<={36,984,1205},'Only the reviewed process-scoped ubsmd group is supported')
        need(os.access('/run/matrix',os.X_OK) and os.access('/run/matrix/memory',os.X_OK) and os.access('/run/matrix/memory/MxmAgentIpcServer',os.W_OK),'Scoped process still cannot reach local SDK socket; no SDK attempt')
        need(not PENDING.exists() and not PENDING.is_symlink(),'Existing B native pending preserved; do not retry')
        need(not SESSION.exists() and SESSION.resolve()==SESSION,'Existing B import work preserved; do not retry')
        need(sha(Path('/usr/lib64/libubsm_sdk.so').resolve(strict=True))==SDK_SHA,'SDK library differs')
        for name,pin in PAYLOAD['headerPins'].items():need(sha(Path('/usr/include')/name)==pin,'SDK public header differs')
        feature=Path('/sys/bus/ub/ub_feature').read_text().splitlines()[0].strip()
        need(int(feature,0)&4,'NC sharing is not advertised')
        SESSION.mkdir(mode=0o700);session_created=True
        package=SESSION/'source';(package/'aenv_ub_provider').mkdir(parents=True,mode=0o700)
        for name,text in PAYLOAD['modules'].items():
            need(Path(name).name==name and name.endswith('.py'),'Unexpected embedded module path')
            (package/'aenv_ub_provider'/name).write_text(text)
        (SESSION/'adapter.cpp').write_text(PAYLOAD['adapter'])
        adapter=SESSION/'libaenv-ub.so'
        with (SESSION/'compile.log').open('xb') as log:
            rc=subprocess.run(['/usr/bin/g++','-std=c++17','-O2','-shared','-fPIC','-pthread','-Wall','-Wextra','-Werror',
                '-I/usr/include',str(SESSION/'adapter.cpp'),'/usr/lib64/libubsm_sdk.so','-Wl,-rpath,/usr/lib64',
                '-Wl,-z,relro,-z,now','-o',str(adapter)],stdout=log,stderr=subprocess.STDOUT,timeout=120).returncode
        need(rc==0,'B SDK adapter compile failed before SDK; preserve compile.log')
        sys.path.insert(0,str(package))
        from aenv_ub_provider import contract,raw,service
        from aenv_ub_provider.io import atomic_json
        manifest_path=SESSION/'owner-manifest.json';atomic_json(manifest_path,owner)
        config={'version':1,'mode':'pmem','role':'import','workDir':str(WORK),'adapter':str(adapter),
            'adapterSha256':'sha256:'+sha(adapter),'region':'default','logicalBudgetBytes':64*1024**2,
            'maxCoverageBytes':128*1024**2,'readerId':'node-b','manifest':str(manifest_path)}
        atomic_json(SESSION/'config.json',config);config=service.load_config(SESSION/'config.json');selected,checked=service.inputs(config)
        need(checked==owner,'Imported manifest identity changed')
        pending={'revision':'B-native-guest-v4','node':'node-b','state':'intent_before_sdk',
                 'SDK_called':None,'workDir':str(WORK),'ownerId':owner['ownerId']}
        with PENDING.open('x') as f:json.dump(pending,f);f.flush();os.fsync(f.fileno())
        parent=os.open(PENDING.parent,os.O_RDONLY|os.O_DIRECTORY|os.O_CLOEXEC)
        try:os.fsync(parent)
        finally:os.close(parent)
        def journal(update):pending.update(update);atomic_json(PENDING,pending)
        report['SDK_called']=None
        prepare_guest(owner)
        run_import(config,selected,owner,service,raw,contract,journal,report)
    except Exception as error:
        report.update(status='STOPPED_B_IMPORT_RELEASE_PRESERVE_RECEIPTS',errorType=type(error).__name__)
        report['reason']=str(error)[:800] if isinstance(error,(RuntimeError,FileNotFoundError)) else 'Inspect private report and pending; no new-name retry'
    finally:
        for fd in OLD_GENERATION_LOCKS:os.close(fd)
        if lock is not None:os.close(lock)
        if session_created:
            with (SESSION/'return.json').open('x') as f:json.dump(report,f,indent=2);f.flush();os.fsync(f.fileno())
        print('BEGIN_B_NATIVE_GUEST_REPORT');print(json.dumps(report,indent=2));print('END_B_NATIVE_GUEST_REPORT')
    return 0 if report['status']=='B_SHARED_BASE_DAX_GUEST_PASSED_AND_RELEASED' else 1



GUEST_LAUNCHER='#!/usr/bin/env python3\n"""Bounded standalone native-pmem Guest mechanism test; never calls the UB SDK.\n\nThe provider owns UB publication/retirement separately. This launcher retains its\nsocket lease until its exact FC child is reaped. No network device, host mount,\nservice, permissions or kernel changes. Default is a read-only plan.\n"""\nimport argparse\nimport array\nimport hashlib\nimport json\nimport os\nfrom pathlib import Path, PurePosixPath\nimport re\nimport shutil\nimport signal\nimport socket\nimport stat\nimport struct\nimport sys\nimport time\nimport uuid\n\nALIGN = 2 * 1024 * 1024\nPASS = \'AENV_DAX_SELFTEST_PASS pmem_count=1 lower_unchanged=1 private_copyup=1\'\nMAX_LOG = 16 * 1024 * 1024\n\n\ndef need(value, reason):\n    if not value:\n        raise ValueError(reason)\n\n\ndef digest(path):\n    h = hashlib.sha256()\n    with path.open(\'rb\') as stream:\n        before = os.fstat(stream.fileno())\n        need(stat.S_ISREG(before.st_mode), \'Pinned input must be a regular file\')\n        for block in iter(lambda: stream.read(1024 * 1024), b\'\'):\n            h.update(block)\n        after = os.fstat(stream.fileno())\n    stamp = lambda s: (s.st_dev, s.st_ino, s.st_size, s.st_mtime_ns)\n    need(stamp(before) == stamp(after) == stamp(path.stat()), \'Pinned input changed while hashing\')\n    return h.hexdigest(), after.st_size\n\n\ndef validate_spec(spec):\n    need(isinstance(spec, dict) and set(spec) == {\'objectId\', \'generation\', \'sha256\', \'bytes\', \'socket\'}, \'Provider spec fields differ\')\n    for key in (\'objectId\', \'generation\'):\n        need(isinstance(spec[key], str) and re.fullmatch(r\'[A-Za-z0-9._-]{1,128}\', spec[key]), \'Invalid object identity\')\n    need(isinstance(spec[\'sha256\'], str) and re.fullmatch(r\'sha256:[0-9a-f]{64}\', spec[\'sha256\']), \'Invalid object SHA256\')\n    need(type(spec[\'bytes\']) is int and ALIGN <= spec[\'bytes\'] <= 1024**3 and spec[\'bytes\'] % ALIGN == 0, \'Invalid complete pmem capacity\')\n    path = spec[\'socket\']\n    need(isinstance(path, str) and PurePosixPath(path).is_absolute() and \'\\0\' not in path and len(path.encode()) < 108, \'Invalid provider socket path\')\n    return spec\n\n\ndef validate_config(config):\n    required = {\'version\', \'providerSpec\', \'firecracker\', \'kernel\', \'tools\', \'upper\', \'expectedProbeSha256\'}\n    need(isinstance(config, dict) and required <= set(config) <= required | {\'memoryMiB\', \'timeoutSecs\', \'traceRunner\', \'seccompFilter\'}, \'Launcher config fields differ\')\n    need(type(config[\'version\']) is int and config[\'version\'] == 1, \'Unsupported launcher config\')\n    validate_spec(config[\'providerSpec\'])\n    for name in (\'firecracker\', \'kernel\', \'tools\', \'upper\') + ((\'traceRunner\',) if \'traceRunner\' in config else ()) + ((\'seccompFilter\',) if \'seccompFilter\' in config else ()):\n        item = config[name]\n        need(isinstance(item, dict) and {\'path\', \'sha256\'} <= set(item) <= {\'path\', \'sha256\', \'bytes\'}, \'Pinned input fields differ\')\n        need(isinstance(item[\'path\'], str) and PurePosixPath(item[\'path\']).is_absolute() and \'\\0\' not in item[\'path\'], \'Input requires absolute real path\')\n        need(isinstance(item[\'sha256\'], str) and re.fullmatch(r\'[0-9a-f]{64}\', item[\'sha256\']), \'Input requires explicit lowercase SHA256\')\n        if \'bytes\' in item:\n            need(type(item[\'bytes\']) is int and item[\'bytes\'] > 0, \'Invalid pinned input length\')\n    need(isinstance(config[\'expectedProbeSha256\'], str) and re.fullmatch(r\'[0-9a-f]{64}\', config[\'expectedProbeSha256\']), \'Missing expected Guest probe SHA256\')\n    need(type(config.get(\'memoryMiB\', 256)) is int and config.get(\'memoryMiB\', 256) in (128, 256), \'Guest RAM must be 128 or 256MiB\')\n    need(type(config.get(\'timeoutSecs\', 120)) is int and 1 <= config.get(\'timeoutSecs\', 120) <= 120, \'Timeout exceeds 120s\')\n    return config\n\n\ndef receive(stream, length):\n    result = bytearray()\n    while len(result) != length:\n        part = stream.recv(length - len(result))\n        if not part:\n            raise EOFError(\'Provider closed a bounded handshake\')\n        result.extend(part)\n    return bytes(result)\n\n\ndef send_json(stream, value):\n    raw = json.dumps(value, separators=(\',\', \':\')).encode()\n    need(len(raw) <= 4096, \'Request exceeds protocol budget\')\n    stream.sendall(struct.pack(\'>I\', len(raw)) + raw)\n\n\ndef receive_json(stream):\n    length = struct.unpack(\'>I\', receive(stream, 4))[0]\n    need(1 <= length <= 4096, \'Response exceeds protocol budget\')\n    return json.loads(receive(stream, length))\n\n\ndef validate_response(response, spec):\n    need(isinstance(response, dict) and set(response) == {\'version\', \'state\', \'backing\', \'privateCow\', \'source\', \'cacheMode\', \'segmentLengths\'}, \'Provider response fields differ\')\n    need(type(response[\'version\']) is int and response[\'version\'] == 2 and response[\'state\'] == \'ready\' and response[\'backing\'] == spec, \'Provider returned another object/generation\')\n    need(response[\'privateCow\'] is False and response[\'source\'] == \'ub\' and response[\'cacheMode\'] == \'nc\', \'Native test requires readonly UB NC, without a RAM CoW claim\')\n    lengths = response[\'segmentLengths\']\n    need(isinstance(lengths, list) and 1 <= len(lengths) <= 32 and all(type(n) is int and n > 0 and n % ALIGN == 0 for n in lengths), \'Malformed native segment list\')\n    need(sum(lengths) == spec[\'bytes\'], \'Segments do not cover complete image\')\n    return lengths\n\n\ndef receive_fds(stream, expected):\n    import fcntl\n    received = []\n    try:\n        payload, ancillary, flags, _ = stream.recvmsg(1, socket.CMSG_SPACE(32 * array.array(\'i\').itemsize), getattr(socket, \'MSG_CMSG_CLOEXEC\', 0))\n        invalid = False\n        for level, kind, data in ancillary:\n            if level == socket.SOL_SOCKET and kind == socket.SCM_RIGHTS:\n                size = array.array(\'i\').itemsize\n                invalid = invalid or len(data) % size != 0\n                values = array.array(\'i\')\n                values.frombytes(data[:len(data) // size * size])\n                received.extend(values)\n            else:\n                invalid = True\n        need(not invalid, \'Unexpected ancillary record\')\n        need(payload == b\'F\' and not flags & (socket.MSG_CTRUNC | socket.MSG_TRUNC) and len(received) == expected, \'Incomplete or extra FD handoff\')\n        for fd in received:\n            fcntl.fcntl(fd, fcntl.F_SETFD, fcntl.FD_CLOEXEC)\n            access = fcntl.fcntl(fd, fcntl.F_GETFL)\n            need(access & os.O_ACCMODE == os.O_RDONLY and access & os.O_SYNC == os.O_SYNC and stat.S_ISCHR(os.fstat(fd).st_mode), \'FD is not readonly O_SYNC character device\')\n        return received\n    except BaseException:\n        for fd in received:\n            os.close(fd)\n        raise\n\n\ndef acquire(spec):\n    import fcntl\n    path = Path(spec[\'socket\'])\n    need(path.resolve(strict=True) == path and path.parent.stat().st_uid == os.geteuid() and not path.parent.stat().st_mode & 0o077, \'Provider socket parent must be private and owned\')\n    meta = path.lstat()\n    need(stat.S_ISSOCK(meta.st_mode) and meta.st_uid == os.geteuid() and not meta.st_mode & 0o077, \'Provider socket identity/permissions differ\')\n    stream = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)\n    pinned = []\n    try:\n        stream.settimeout(10)\n        stream.connect(str(path))\n        peer = struct.unpack(\'3i\', stream.getsockopt(socket.SOL_SOCKET, socket.SO_PEERCRED, 12))\n        need(peer[0] > 0 and peer[1] == os.geteuid(), \'Provider UID differs\')\n        send_json(stream, {\'version\': 2, \'operation\': \'acquire\', \'objectId\': spec[\'objectId\'], \'generation\': spec[\'generation\'], \'sha256\': spec[\'sha256\'], \'bytes\': spec[\'bytes\'], \'privateCow\': False})\n        lengths = validate_response(receive_json(stream), spec)\n        received = receive_fds(stream, len(lengths))\n        try:\n            for fd in received:\n                pinned.append(fcntl.fcntl(fd, fcntl.F_DUPFD_CLOEXEC, 512))\n        finally:\n            for fd in received:\n                os.close(fd)\n        lease = fcntl.fcntl(stream.fileno(), fcntl.F_DUPFD_CLOEXEC, 512)\n        pinned.append(lease)\n        stream.settimeout(None)\n        descriptor = \'aenv-pmem-fd:v2:\' + str(spec[\'bytes\']) + \':nc:\' + \',\'.join(str(64+i) + \'@\' + str(n) for i, n in enumerate(lengths))\n        return stream, pinned[:-1], lease, descriptor, {\'pid\': peer[0], \'uid\': peer[1], \'gid\': peer[2]}, lengths\n    except BaseException:\n        for fd in pinned:\n            os.close(fd)\n        stream.close()\n        raise\n\n\ndef build_fc_config(config, upper, descriptor):\n    return {\'boot-source\': {\'kernel_image_path\': config[\'kernel\'][\'path\'], \'boot_args\':\n        \'console=ttyS0 reboot=k panic=1 pci=off root=/dev/vda ro init=/init aenv_pmem_rootfs=1 aenv_pmem_fstype=ext4 aenv_dax_selftest=1\'},\n        \'drives\': [{\'drive_id\': \'tools\', \'path_on_host\': config[\'tools\'][\'path\'], \'is_root_device\': True, \'is_read_only\': True, \'io_engine\': \'Sync\'},\n                   {\'drive_id\': \'upper\', \'path_on_host\': str(upper), \'is_root_device\': False, \'is_read_only\': False, \'io_engine\': \'Sync\'}],\n        \'machine-config\': {\'vcpu_count\': 1, \'mem_size_mib\': config.get(\'memoryMiB\', 256), \'smt\': False, \'track_dirty_pages\': False},\n        \'pmem\': [{\'id\': \'base0\', \'path_on_host\': descriptor, \'root_device\': False, \'read_only\': True}], \'network-interfaces\': []}\n\n\ndef classify(stdout, stderr, expected, exit_code):\n    lines = [line.strip(\'\\r\') for line in stdout.splitlines()]\n    base = re.fullmatch(r\'AENV_DAX_SELFTEST_BASE ([0-9a-f]{64})  /mnt/ro0/\\.aenv-dax-probe\', next((line for line in lines if line.startswith(\'AENV_DAX_SELFTEST_BASE \')), \'\'))\n    return {\'passMarkerObserved\': lines.count(PASS) == 1, \'guestProbeHashMatches\': bool(base and base[1] == expected),\n        \'failureMarkerObserved\': \'AENV_DAX_SELFTEST_FAIL\' in stdout or \'AENV_DAX_SELFTEST_FAIL\' in stderr,\n        \'guestDaxSelftestPassed\': exit_code == 0 and lines.count(PASS) == 1 and bool(base and base[1] == expected)\n            and \'AENV_DAX_SELFTEST_FAIL\' not in stdout and \'AENV_DAX_SELFTEST_FAIL\' not in stderr}\n\n\ndef save(path, value):\n    temp = path.with_name(path.name + \'.new\')\n    with temp.open(\'x\', encoding=\'utf-8\') as stream:\n        json.dump(value, stream, indent=2)\n        stream.flush()\n        os.fsync(stream.fileno())\n    os.replace(temp, path)\n\n\ndef wait_child(pid, seconds):\n    deadline = time.monotonic() + seconds\n    while True:\n        found, status = os.waitpid(pid, os.WNOHANG)\n        if found == pid:\n            return os.waitstatus_to_exitcode(status)\n        if time.monotonic() >= deadline:\n            return None\n        time.sleep(0.1)\n\n\ndef terminate_child(pid):\n    for sig, seconds in ((signal.SIGTERM, 5), (signal.SIGKILL, 5)):\n        try:\n            os.kill(pid, sig)\n        except ProcessLookupError:\n            pass\n        code = wait_child(pid, seconds)\n        if code is not None:\n            return code\n    return None\n\n\ndef run(config, output):\n    import fcntl\n    import resource\n    need(sys.platform == \'linux\' and os.uname().machine == \'aarch64\' and os.getuid() == os.geteuid() != 0, \'Use ordinary ARM64 Linux account\')\n    caps = dict(line.split(\':\', 1) for line in Path(\'/proc/self/status\').read_text().splitlines() if \':\' in line)\n    need(all(int(caps[k].strip(), 16) == 0 for k in (\'CapInh\', \'CapPrm\', \'CapEff\', \'CapAmb\')), \'Launcher requires zero capabilities\')\n    resource.setrlimit(resource.RLIMIT_CORE, (0, 0))\n    need(resource.getrlimit(resource.RLIMIT_NOFILE)[0] >= 600, \'FD limit too small; no host setting is changed\')\n    kvm = os.open(\'/dev/kvm\', os.O_RDWR | os.O_CLOEXEC | os.O_NOFOLLOW)\n    try:\n        need(stat.S_ISCHR(os.fstat(kvm).st_mode), \'KVM path is not a character device\')\n    finally:\n        os.close(kvm)\n    need(output.is_absolute() and output.resolve() == output and not output.exists() and output.parent.is_dir(), \'Output must be a new absolute nonredirected directory\')\n    need(shutil.disk_usage(output.parent).free >= 2 * 1024**3, \'Need 2GiB free for isolated upper/logs\')\n    limits = {\'firecracker\': 256*1024**2, \'kernel\': 256*1024**2, \'tools\': 512*1024**2, \'upper\': 1024**3}\n    if \'traceRunner\' in config:\n        limits[\'traceRunner\'] = 16 * 1024**2\n    if \'seccompFilter\' in config:\n        limits[\'seccompFilter\'] = 100000\n    pinned = {}\n    for key, limit in limits.items():\n        item = config[key]\n        path = Path(item[\'path\'])\n        need(path.resolve(strict=True) == path and path.is_file() and 0 < path.stat().st_size <= limit, \'Input path/type/budget differs: \' + key)\n        observed, count = digest(path)\n        need(observed == item[\'sha256\'] and (\'bytes\' not in item or count == item[\'bytes\']), \'Input pin differs: \' + key)\n        pinned[key] = {\'sha256\': observed, \'bytes\': count}\n    required_file_limit = max(MAX_LOG, pinned[\'upper\'][\'bytes\'])\n    hard_limit = resource.getrlimit(resource.RLIMIT_FSIZE)[1]\n    need(hard_limit == resource.RLIM_INFINITY or hard_limit >= required_file_limit, \'Existing file-size limit is below private upper size\')\n    resource.setrlimit(resource.RLIMIT_FSIZE, (required_file_limit, required_file_limit))\n    signal.signal(signal.SIGCHLD, signal.SIG_DFL)\n    os.umask(0o077)\n    output.mkdir(mode=0o700)\n    report = {\'revision\': \'native-pmem-guest-node-b-v1\', \'state\': \'inputs_verified_no_guest\', \'SDK_called\': False,\n        \'fullAgentENVIntegrationAccepted\': False, \'crossNodeAccepted\': False, \'netPhysicalSavingsAccepted\': False,\n        \'safeToRetireThisLease\': False, \'pinnedInputs\': pinned, \'providerSpec\': config[\'providerSpec\']}\n    save(output/\'return.json\', report)\n    upper = output/\'private-upper.ext4\'\n    shutil.copyfile(config[\'upper\'][\'path\'], upper)\n    need(digest(upper)[0] == pinned[\'upper\'][\'sha256\'], \'Private upper copy differs\')\n    stream = None\n    data = []\n    lease = None\n    pid = None\n    reaped = False\n    try:\n        stream, data, lease, descriptor, peer, lengths = acquire(config[\'providerSpec\'])\n        report.update(state=\'provider_lease_acquired\', providerPeer=peer, segmentLengths=lengths, descriptor=descriptor)\n        fc_config = output/\'firecracker.json\'\n        fc_config.write_text(json.dumps(build_fc_config(config, upper, descriptor), indent=2))\n        save(output/\'return.json\', report)\n        env = dict(os.environ)\n        for key in (\'LD_PRELOAD\', \'LD_AUDIT\'):\n            env.pop(key, None)\n        with (output/\'serial.stdout.log\').open(\'xb\') as stdout, (output/\'firecracker.stderr.log\').open(\'xb\') as stderr, open(\'/dev/null\', \'rb\') as stdin:\n            actions = [(os.POSIX_SPAWN_DUP2, fd, 64+i) for i, fd in enumerate(data)]\n            actions.extend([(os.POSIX_SPAWN_DUP2, lease, 42), (os.POSIX_SPAWN_DUP2, stdin.fileno(), 0),\n                (os.POSIX_SPAWN_DUP2, stdout.fileno(), 1), (os.POSIX_SPAWN_DUP2, stderr.fileno(), 2)])\n            argv = [config[\'firecracker\'][\'path\'], \'--no-api\', \'--config-file\', str(fc_config), \'--id\', \'native-pmem-\' + uuid.uuid4().hex]\n            if \'seccompFilter\' in config:\n                argv.extend([\'--seccomp-filter\', config[\'seccompFilter\'][\'path\']])\n            if \'traceRunner\' in config:\n                argv.insert(0, config[\'traceRunner\'][\'path\'])\n            pid = os.posix_spawn(argv[0], argv, env, file_actions=actions, setsid=True)\n            report.update(state=\'owned_firecracker_running\', firecrackerPid=pid, Guest_created=True)\n            save(output/\'return.json\', report)\n            code = wait_child(pid, config.get(\'timeoutSecs\', 120))\n            timed_out = code is None\n            if timed_out:\n                code = terminate_child(pid)\n            reaped = code is not None\n            report.update(firecrackerExit=code, timedOut=timed_out, firecrackerReaped=reaped)\n        need(reaped, \'FC not definitively reaped; inherited lease remains pinned, preserve all provider resources\')\n        out, err = output/\'serial.stdout.log\', output/\'firecracker.stderr.log\'\n        need(out.stat().st_size <= MAX_LOG and err.stat().st_size <= MAX_LOG, \'FC log budget exceeded; Guest result refused\')\n        stdout_text, stderr_text = out.read_text(errors=\'replace\'), err.read_text(errors=\'replace\')\n        report.update(classify(stdout_text, stderr_text, config[\'expectedProbeSha256\'], code))\n        report[\'serialTail\'] = stdout_text[-16000:]\n        report[\'stderrTail\'] = stderr_text[-8000:]\n        if \'traceRunner\' in config:\n            diagnostics, final = [], []\n            for line in stdout_text.splitlines():\n                if line.startswith(\'AENV_SIGSYS_DIAGNOSTIC \'):\n                    diagnostics.append(json.loads(line.split(\' \', 1)[1]))\n                if line.startswith(\'AENV_TRACE_FINAL \'):\n                    final.append(json.loads(line.split(\' \', 1)[1]))\n            report[\'sigsysDiagnostics\'] = diagnostics\n            report[\'traceFinal\'] = final\n            report[\'allOwnedTraceesReaped\'] = len(final) == 1 and final[0].get(\'allOwnedTraceesReaped\') is True\n            report[\'Guest_creation_attempted\'] = True\n            report[\'Guest_created\'] = True if report.get(\'guestDaxSelftestPassed\') else None\n            if diagnostics or not report[\'allOwnedTraceesReaped\']:\n                report[\'guestDaxSelftestPassed\'] = False\n        if timed_out:\n            report[\'guestDaxSelftestPassed\'] = False\n        for key in pinned:\n            need(digest(Path(config[key][\'path\']))[0] == pinned[key][\'sha256\'], \'Original pinned input changed: \' + key)\n        report[\'state\'] = \'native_pmem_guest_mechanism_passed\' if report[\'guestDaxSelftestPassed\'] else \'native_pmem_guest_mechanism_failed\'\n        report[\'privateUpperBytes\'] = upper.stat().st_size\n    except BaseException as error:\n        if pid is not None and not reaped:\n            try:\n                code = terminate_child(pid)\n                reaped = code is not None\n                report.update(firecrackerExit=code, firecrackerReaped=reaped)\n            except BaseException:\n                pass\n        report.update(state=\'failed_preserve_evidence\', errorType=type(error).__name__, reason=str(error)[:1500], guestDaxSelftestPassed=False)\n    finally:\n        safe = (pid is None or reaped) and (\'traceRunner\' not in config or pid is None or report.get(\'allOwnedTraceesReaped\') is True)\n        report[\'safeToRetireThisLease\'] = safe\n        if safe:\n            for fd in data:\n                os.close(fd)\n            if lease is not None:\n                os.close(lease)\n            if stream is not None:\n                stream.close()\n        report[\'scope\'] = \'Standalone readonly NC pmem/ext4/DAX and private upper mechanism; no RAM CoW or global memory accounting\'\n        save(output/\'return.json\', report)\n    print(json.dumps(report, indent=2))\n    return 0 if report.get(\'guestDaxSelftestPassed\') and report[\'safeToRetireThisLease\'] else 1\n\n\ndef main():\n    parser = argparse.ArgumentParser(description=__doc__)\n    parser.add_argument(\'--config\', required=True)\n    parser.add_argument(\'--output\', required=True)\n    parser.add_argument(\'--run\', action=\'store_true\')\n    args = parser.parse_args()\n    path = Path(args.config)\n    need(path.is_file() and path.stat().st_size <= 32768, \'Missing/oversize explicit launcher config\')\n    config = validate_config(json.loads(path.read_text()))\n    if not args.run:\n        print(json.dumps({\'status\': \'PLAN_ONLY_NO_GUEST_NO_SDK\', \'providerSpec\': config[\'providerSpec\'],\n            \'memoryMiB\': config.get(\'memoryMiB\', 256), \'timeoutSecs\': config.get(\'timeoutSecs\', 120),\n            \'Guest_created\': False, \'SDK_called\': False, \'services_changed\': False}, indent=2))\n        return 0\n    return run(config, Path(args.output).absolute())\n\nif __name__ == \'__main__\':\n    raise SystemExit(main())\n'
