def check_retired_endpoints(directory):
    # The production raw provider unlinks data.sock, while service.serve closes
    # control.sock without unlinking its pathname. Hold generation.lock first.
    data=directory/'data.sock'
    need(not data.exists() and not data.is_symlink(),'Prior B data endpoint remains; preserve and stop')
    control=directory/'control.sock'
    need(not control.is_symlink(),'Prior B control endpoint redirected')
    if not control.exists():return {'dataSocketAbsent':True,'controlSocketAbsent':True,'oldFilesModified':False}
    need(control.resolve(strict=True)==control,'Prior control path redirected')
    before=control.lstat()
    need(stat.S_ISSOCK(before.st_mode) and before.st_uid==1204 and before.st_gid==1205
         and stat.S_IMODE(before.st_mode)==0o600 and before.st_nlink==1,'Unexpected old control socket identity')
    import errno
    with socket.socket(socket.AF_UNIX,socket.SOCK_STREAM) as probe:
        probe.settimeout(2)
        try:probe.connect(str(control))
        except OSError as error:
            need(error.errno==errno.ECONNREFUSED,'Old control socket not proven inactive; stop')
        else:raise RuntimeError('Prior control socket is still live; stop without a request')
    after=control.lstat()
    stamp=lambda s:(s.st_dev,s.st_ino,s.st_uid,s.st_gid,s.st_mode,s.st_nlink)
    need(stamp(before)==stamp(after),'Old control endpoint changed during check')
    return {'dataSocketAbsent':True,'controlSocketAbsent':False,'controlConnectErrno':'ECONNREFUSED',
            'controlSocketInode':before.st_ino,'oldFilesModified':False,'generationLockHeld':True}

def previous_failure_proof():
    import fcntl
    proof=previous_initial_failure_proof()
    need(not (BASE/'native-guest-v3').exists() and not (ROOT/'relay/native-pmem-node-b-guest-v3.pending.json').exists(), 'Prior v3 progressed beyond pre-SDK check; preserve and stop')
    need(36 in os.getgroups(),'Reviewed KVM process group is missing')
    old=BASE/'native-import-release-v2'
    report=read(old/'return.json');receipt=read(old/'provider/release.json');state=read(old/'provider/owner.json')
    owner=manifest()
    need(report.get('status')=='B_EXACT_GENERATION_IMPORTED_SHA_VERIFIED_AND_RELEASED'
         and report.get('ownerId')==owner['ownerId'] and report.get('manifestSha256')==MANIFEST_SHA
         and report.get('allocationCalls')==0 and report.get('deallocationCalls')==0
         and all(report.get(k) is True for k in ('mappingsReleased','finalizeAcknowledged','fullPayloadShaVerifiedBeforeRelease','fullPayloadShaVerifiedAfterImport')),
         'Prior B v2 import did not fully release; do not reimport')
    expected={'version':1,'ownerId':owner['ownerId'],'readerId':'node-b','manifestSha256':'sha256:'+MANIFEST_SHA,'state':'released'}
    need(receipt==expected and report.get('release')==expected and state.get('state')=='released'
         and state.get('finalize_acknowledged') is True and state.get('base_post_sha256_verified') is True
         and state.get('objects')==[], 'Prior B v2 production release evidence differs')
    lock=old/'provider/generation.lock';need(lock.resolve(strict=True)==lock,'Prior B lock redirected')
    fd=os.open(lock,os.O_RDONLY|os.O_NOFOLLOW|os.O_CLOEXEC)
    try:
        meta=os.fstat(fd);need(stat.S_ISREG(meta.st_mode) and meta.st_uid==1204 and meta.st_nlink==1,'Prior B lock differs')
        fcntl.flock(fd,fcntl.LOCK_EX|fcntl.LOCK_NB)
    except BaseException:os.close(fd);raise
    OLD_GENERATION_LOCKS.append(fd)
    proof['priorV2Endpoints']=check_retired_endpoints(old/'provider')
    proof.update(priorV2ExplicitlyReleased=True,priorV2GenerationLockHeld=True,
        priorReleaseMustNotRetireAWhileThisRunIsActive=True)
    return proof

def guest_config(owner):
    artifact=read(BASE/'return.json')
    need(artifact.get('node')=='node-b' and artifact.get('originalToolsUnchanged') is True,'B prepared artifacts missing')
    inputs=artifact['guestInputs']
    pins={'kernel':'04b12a7409b60c63bc807148826969d30ecb4d93a88ffc7690c22bcc06676752',
          'tools':'ba7821099c33b3ae33cbe5b9aec89b31f9e1e860f086465ecb73d8e98cb09288',
          'upper':'c81352f1f8fc9d4036c475fe8dba5089bd7fcdbd688ca7a9f0a3e816d8796f4c'}
    for key,pin in pins.items():need(inputs[key]['sha256']==pin and sha(Path(inputs[key]['path']))==pin,'B input differs: '+key)
    need(RECEIVE.resolve(strict=True)==RECEIVE and RECEIVE.stat().st_uid==1204,'Received artifacts directory differs')
    need(sha(RECEIVE/'firecracker')==FC_PIN and sha(RECEIVE/'policy.bpf')==FILTER_PIN,'A-validated FC/filter missing or changed')
    identity=owner['replicas'][0]['identity']
    spec=dict(identity,socket=str(WORK/'data.sock'))
    return {'version':1,'providerSpec':spec,
            'firecracker':{'path':str(RECEIVE/'firecracker'),'sha256':FC_PIN,'bytes':8505784},
            'seccompFilter':{'path':str(RECEIVE/'policy.bpf'),'sha256':FILTER_PIN,'bytes':2810},
            'kernel':inputs['kernel'],'tools':inputs['tools'],'upper':inputs['upper'],
            'expectedProbeSha256':'6ed4c221615a18a3f586110b10493d1889ef75f760f8eb939b69e44d20f49158',
            'memoryMiB':256,'timeoutSecs':120}

def prepare_guest(owner):
    config=guest_config(owner)
    need(os.access('/dev/kvm',os.R_OK|os.W_OK),'KVM access missing; no SDK attempt')
    version=subprocess.run([config['firecracker']['path'],'--version'],capture_output=True,text=True,timeout=10)
    need(version.returncode==0 and 'Firecracker' in version.stdout,'Received FC cannot load on B; no SDK attempt')
    (SESSION/'guest-launcher.py').write_bytes(GUEST_LAUNCHER.encode())
    (SESSION/'guest-config.json').write_text(json.dumps(config,indent=2))

def run_guest_after_import():
    with (SESSION/'guest-launcher.log').open('xb') as log:
        process=subprocess.Popen([sys.executable,'-I','-B',str(SESSION/'guest-launcher.py'),
            '--config',str(SESSION/'guest-config.json'),'--output',str(SESSION/'guest-result'),'--run'],
            stdout=log,stderr=subprocess.STDOUT,start_new_session=True)
        try:code=process.wait(timeout=150)
        except subprocess.TimeoutExpired:
            return {'safeToRetireThisLease':False,'reason':'Launcher timeout; leave provider and lease intact','launcherPid':process.pid}
    path=SESSION/'guest-result/return.json'
    if not path.exists():
        print('B_GUEST_NO_REPORT_PRESERVE_PROVIDER',flush=True)
        return {'safeToRetireThisLease':False,'launcherExit':code,'launcherLog':str(SESSION/'guest-launcher.log')}
    result=read(path);result['launcherExit']=code
    return result

def prepare_root():
    need(sys.platform=='linux' and socket.gethostname()=='agent1' and os.getuid()==os.geteuid()==1204,'Use ordinary B jwk terminal')
    owner=manifest();guest_config(owner)
    need(not SESSION.exists() and not PENDING.exists(),'Existing guest work/receipt preserved; do not repeat')
    path=Path(__file__).resolve(strict=True);need(path==ROOT/'B_native_dax_guest_v4.py','Use reviewed fixed script location')
    print('BEGIN_B_NATIVE_DAX_GUEST_REVIEWED_ROOT')
    print(ROOT_REVIEW_TEMPLATE.replace('__PINNED_SOURCE_SHA__',sha(path)))
    print('END_B_NATIVE_DAX_GUEST_REVIEWED_ROOT')
    return 0

if __name__=='__main__':
    if sys.argv[1:]==['--prepare-root']:raise SystemExit(prepare_root())
    raise SystemExit(main())
